//! `chrome-cdp completions <shell>` (plan 08, milestone 8.3): a shell
//! completion script, generated by `clap_complete` from the clap
//! definitions, so it knows every command and flag.

use clap::CommandFactory as _;
use protocol::Output;
use protocol::schema::CompletionsData;

use crate::cli::{Cli, CompletionsArgs};

pub(crate) fn run(args: &CompletionsArgs) -> Output {
    // clap_complete offers hidden commands too; the daemon is not one to
    // type.
    let root = Cli::command();
    let mut cmd = clap::Command::new(protocol::PROGRAM)
        .disable_help_subcommand(true)
        .disable_version_flag(true)
        .args(root.get_arguments().cloned())
        .subcommands(root.get_subcommands().filter(|c| !c.is_hide_set()).cloned());
    let mut script = Vec::new();
    clap_complete::generate(args.shell, &mut cmd, protocol::PROGRAM, &mut script);
    let mut script = String::from_utf8_lossy(&script).into_owned();
    if args.shell == clap_complete::Shell::Bash {
        // clap_complete 4.6 names a subcommand's case `chrome__cdp__subcmd__x`
        // where it matches and `chrome__subcmd__cdp__subcmd__x` where it
        // completes, for a program name with a `-`; make them agree.
        script = script.replace("chrome__subcmd__cdp__subcmd__", "chrome__cdp__subcmd__");
    }
    let data = CompletionsData {
        shell: args.shell.to_string(),
        script: script.clone(),
    };
    let shown = script.trim_end().to_owned();
    Output::typed(&data, shown.clone()).quiet(shown)
}
